                        Для разработки программных решений и приложений, тестирования 
                        и настройки нашего оборудования для партнёров и заказчиков 
                        создан специальный портал wiki.atb-e.ru с расширенной 
                        документацией и собственным GitLab.
                    </p>


                    <div class="hr-polt--div__IMAGES_MAIN">
                        <div class="hr-polt--div__IMAGES __C-SCRL DOWN">
                            <div class="hr-polt--div__IMAGE_CONT">
                                <img class="hr-polt--img__IMAGE" src="images/home/hm-des_3.png" alt="" loading="lazy">
                            </div>
                            <div class="hr-polt--div__IMAGE_ADD1"></div>
                            <div class="hr-polt--div__IMAGE_ADD2"></div>
                        </div>
    
                        <div class="hr-polt--div__IMAGES_TEXT __C-SCRL LEFT">
                            <p class="st-main--p__DESCR1 __C-SCRL DOWN">
                                Мы стараемся обеспечить инженерно-технический, 
                                производственный и административный персонал всем 
                                необходимым оборудованием для выполнения задач и 
                                создать комфортные условия для продуктивной работы.
                            </p>
        
                            <p class="st-main--p__DESCR2 _THIRD __C-SCRL DOWN"> 
                                При выходе на работу в «АТБ Электроника» сотрудники 
                                включаются в индивидуальную программу адаптации и обучения.
                                Формулируются задачи и ожидаемые результаты. В процессе 
                                обеспечивается конструктивная обратная связь.
                            </p>
        
                            <a class="hr-polt--a__DETAIL __C-SCRL DOWN" href="#">
                                <span class="hr-polt--span__DETAIL">
                                    Подробнее о процессе адаптации
                                </span>
                                <svg class="hr-polt--svg__DETAIL" width="28" height="22" viewBox="0 0 28 22" fill="none" xmlns="http://www.w3.org/2000/svg">
                                    <path d="M0 10.6953H27.5M27.5 10.6953L17 0.195312M27.5 10.6953L17 21.1953" stroke="#59CD90" stroke-width="0.55"/>
                                </svg>
                            </a>
                        </div>
                    </div>
                    

                    <div class="hr-polt--div__IMAGES_MAIN _SECOND">
                        <div class="hr-polt--div__IMAGES _SECOND __C-SCRL DOWN">
                            <div class="hr-polt--div__IMAGE_CONT">
                                <img class="hr-polt--img__IMAGE" src="images/home/hm-des_1.png" alt="" loading="lazy">
                            </div>
                            <div class="hr-polt--div__IMAGE_ADD1 _SECOND"></div>
                            <div class="hr-polt--div__IMAGE_ADD2 _SECOND"></div>
                        </div>

                        <div class="hr-polt--div__IMAGES_TEXT _SECOND __C-SCRL RIGHT">
                            <p class="st-main--p__DESCR1 _SECOND __C-SCRL DOWN">
                                Каждый сотрудник нашей команды является не только специалистом 
                                и профессионалом, но также личностью с индивидуальными желаниями, 
                                потребностями и мотивацией. Мы понимаем, что приоритетом является 
                                баланс между профессиональным развитием и ростом, материальным 
                                благополучием и возможностью вести интересную, здоровую и 
                                насыщенную личную жизнь, заботиться о семье и близких.
                            </p>
        
                            <p class="st-main--p__DESCR2 _SECOND __C-SCRL DOWN"> 
                                Для этого мы обеспечиваем комфортные условия работы, 
                                развиваем корпоративные программы медицинского страхования, 
                                оплаты фитнеса, проводим тренинги, корпоративные мероприятия 
                                и тимбилдинги.
                            </p>
        
                            <p class="st-main--p__DESCR2 __C-SCRL DOWN"> 
                                Ежедневное время работы в компании сокращено на 30 минут за счёт 
                                уменьшения времени обеденного перерыва. В пятницу рабочий день 
                                сокращён на час для сохранения баланса работа/жизнь.
                            </p>
        
                            <a class="hr-polt--a__DETAIL _SECOND __C-SCRL DOWN" href="#">
                                <span class="hr-polt--span__DETAIL">
                                    Подробная информация о преимуществах 
                                    работы в «АТБ Электроника» 
                                </span>
                                <svg class="hr-polt--svg__DETAIL" width="28" height="22" viewBox="0 0 28 22" fill="none" xmlns="http://www.w3.org/2000/svg">
                                    <path d="M0 10.6953H27.5M27.5 10.6953L17 0.195312M27.5 10.6953L17 21.1953" stroke="#59CD90" stroke-width="0.55"/>
                                </svg>
                            </a>
                        </div>
                    </div>
                    

                    <p class="st-main--p__DESCR1 _LAST __C-SCRL DOWN">
                        Мы рады видеть в нашей команде ярких, творческих, 
                        грамотных и мотивированных профессионалов, готовых 
                        расти и развиваться вместе с компанией - ждём вас!
                    </p>

                    <p class="st-main--p__DESCR2 _LAST __C-SCRL DOWN"> 
                        Ответы на важные и часто встречающиеся вопросы мы постарались сформулировать в разделе
                        <a class="st-main--a__DESCR2" href="#">
                            F.A.Q
                        </a> 
                    </p>

                    <button class="hr-polt--button__ELSE _HIDE __C-SCRL DOWN">
                        <span class="hr-polt--span__ELSE">
                            скрыть
                        </span>
                        <svg class="hr-polt--svg__ELSE" width="22" height="28" viewBox="0 0 22 28" fill="none" xmlns="http://www.w3.org/2000/svg">
