                                            <clipPath id="clip0_4202_2299">
                                            <rect width="44" height="32" fill="white"></rect>
                                            </clipPath>
                                            </defs>
                                        </svg>
                                    </div>
                                </div>
                                <div class="hr-hst--div__POPUP_BODY_TEXT __C-SCRL DOWN">
                                    <p class="st-main--p__DESCR2"> 
                                        Мой профессиональный путь в компании начался 
                                        с позиции инженера-схемотехника. В первый год 
                                        работы я был сосредоточен на разработке устройств 
                                        для направления IoT — это стало прочной инженерной 
                                        базой и позволило глубоко погрузиться в полный 
                                        цикл создания аппаратных решений.
                                    </p>
    
                                    <p class="st-main--p__DESCR2"> 
                                        В течение первых двух лет мне удалось разработать 
                                        линейку базовых станций LoRaWAN, что стало важным 
                                        этапом как для продукта, так и для моего профессионального 
                                        роста. В результате я перешёл на позицию старшего 
                                        инженера-схемотехника и начал работу над промышленными 
                                        компьютерами, ориентированными на различные рынки и 
                                        сценарии применения.
                                    </p>
    
                                    <p class="st-main--p__DESCR2"> 
                                        Следующий этап — должность ведущего инженера-схемотехника. 
                                        В этой роли я выпустил полноценную линейку промышленных 
                                        компьютеров, объединяющую требования надёжности, масштабируемости 
                                        и технологической зрелости. Этот опыт стал логичным основанием 
                                        для перехода на позицию руководителя отдела проектирования.
                                    </p>
    
                                    <p class="st-main--p__DESCR2"> 
                                        Сегодня я отвечаю не только за технические решения, 
                                        но и за развитие команды, архитектурную целостность 
                                        проектов и качество инженерных подходов. Я убеждён, 
                                        что устойчивый рост компании невозможен без сильной 
                                        инженерной культуры, ответственности за результат и 
                                        постоянного стремления делать продукты лучше, чем вчера. 
                                        Именно такой подход позволяет нам уверенно двигаться 
                                        вперёд и создавать решения, которыми можно 
                                        по-настоящему гордиться.
                                    </p>
                                </div>
                            </div>
                        </div>
                    </div>


