        <!-- ---------- ********** СЕКЦИЯ FAQ ********** ---------- -->


        <section class="hr-faq" id="hr-faq">
            <div class="hr-faq--div__CONT C-CONTAINER">
                <h2 class="c-common--h2 __C-SCRL RIGHT">
                    F.A.Q.
                </h2>


                <div class="hr-faq--div__MAIN">
                    <div class="hr-faq--div__LEFT __C-SCRL DOWN">
                        <p class="hr-faq--p__LEFT_TOP">
                            Отвечаем на важные вопросы
                        </p>

                        <div class="hr-faq--div__IMAGES">
                            <div class="hr-faq--div__IMAGE_CONT">
                                <img class="hr-faq--img__IMAGE" src="images/home/hm-des_2.png" alt="" loading="lazy">
                            </div>
                            <div class="hr-faq--div__IMAGE_ADD1"></div>
                            <div class="hr-faq--div__IMAGE_ADD2"></div>
                        </div>
                    </div>


                    <ul class="hr-faq--ul__LIST __C-SCRL RIGHT">
                        <li class="hr-faq--li__LIST __C-SCRL DOWN">
                            <button class="hr-faq--button__LIST_TOP">
                                <p class="hr-faq--p__LIST_TOP">
                                    <span class="hr-faq--span__LIST_TOP">
                                        Как добраться до офиса / производства?
                                    </span>
                                </p>
                                
                                <div class="hr-faq--div__LIST_TOP">
                                    <svg class="hr-faq--svg__LIST_TOP" width="14" height="7" viewBox="0 0 14 7" fill="none" xmlns="http://www.w3.org/2000/svg">
                                        <path d="M0.5 0.5L7 6.61765L13.5 0.500001" stroke="white" stroke-linecap="round"/>
                                    </svg>
                                </div>
                            </button>


                            <div class="hr-faq--div__LIST_BOTTOM">
                                <p class="st-main--p__DESCR2"> 
                                    Наш офис находится в комфортабельном бизнес-центре 
                                    в шаговой доступности от метро «Отрадное». 
                                    Карту проезда и видео можно найти
                                    <a class="st-main--a__DESCR2" href="#">
                                        здесь
                                    </a>.
                                </p>
                                <p class="st-main--p__DESCR2"> 
                                    Производство находится недалек от станции метро «ВДНХ». 
                                    Карту проезда можно найти
                                    <a class="st-main--a__DESCR2" href="#">
                                        здесь
                                    </a>.
                                </p>
                            </div>
                        </li>

                        <li class="hr-faq--li__LIST __C-SCRL DOWN">
                            <button class="hr-faq--button__LIST_TOP">
                                <p class="hr-faq--p__LIST_TOP">
                                    <span class="hr-faq--span__LIST_TOP">
                                        Как формулируются задачи на испытательный срок и оцениваются результаты?
                                    </span>
                                </p>
                                
                                <div class="hr-faq--div__LIST_TOP">
                                    <svg class="hr-faq--svg__LIST_TOP" width="14" height="7" viewBox="0 0 14 7" fill="none" xmlns="http://www.w3.org/2000/svg">
                                        <path d="M0.5 0.5L7 6.61765L13.5 0.500001" stroke="white" stroke-linecap="round"/>
                                    </svg>
                                </div>
                            </button>


                            <div class="hr-faq--div__LIST_BOTTOM">
                                <p class="st-main--p__DESCR2"> 
                                    Задачи на испытательный срок формулируются после прохождения 
                                    обучения и вводной программы адаптации по модели S.M.A.R.T. 
                                    (Стратегические, измеримые, амбициозные, реалистичные и 
                                    ограниченные во времени). Они согласовываются с сотрудником, 
                                    непосредственным руководителем и отделом персонала.
                                </p>
                                <p class="st-main--p__DESCR2"> 
                                    При окончании испытательного срока составляется отчёт по 
                                    результатам, на основании принимается решение о дальнейшей 
                                    работе и профессиональном развитии.
                                </p>
                            </div>
                        </li>

                        <li class="hr-faq--li__LIST __C-SCRL DOWN">
                            <button class="hr-faq--button__LIST_TOP">
                                <p class="hr-faq--p__LIST_TOP">
                                    <span class="hr-faq--span__LIST_TOP">
                                        Даётся ли обратная связь?
                                    </span>
