                    <div class="hr-blog--div__POPUP">
                        <div class="hr-blog--div__POPUP_CONT">
                            <button class="hr-blog--button__POPUP_CLOSE">
                                <svg class="hr-blog--svg__POPUP_CLOSE" width="15" height="15" viewBox="0 0 15 15" fill="none" xmlns="http://www.w3.org/2000/svg">
                                    <rect width="19.6727" height="1.50269" rx="0.751343" transform="matrix(0.705843 -0.708368 0.705843 0.708368 0 13.9355)" fill="#005792"></rect>
                                    <rect width="19.6727" height="1.50269" rx="0.751343" transform="matrix(-0.705843 -0.708368 -0.705843 0.708368 15 13.9355)" fill="#005792"></rect>
                                </svg>
                            </button>

                            <div class="hr-blog--div__POPUP_TOP">
                                <p class="hr-blog--p__POPUP_NAME __C-SCRL DOWN">
                                    7 Мультимедийные системы промышленных встроенных одноплатных мини-компьютеров
                                </p>
                                <p class="hr-blog--p__POPUP_DATE __C-SCRL DOWN">
                                    27.06.2025
                                </p>
                            </div>

                            <div class="hr-blog--div__POPUP_TEXT1">
                                <p class="st-main--p__DESCR1 __C-SCRL DOWN"> 
                                    Мы работаем над важной задачей импортозамещения и 
                                    обеспечения Российских компаний и организаций передовым, 
                                    надежным, технологичным и конкурентоспособным отечественным 
                                    оборудованием.
                                </p>
                                <p class="st-main--p__DESCR2 __C-SCRL DOWN"> 
                                    В современном высококонкурентном мире электротехническая отрасль 
                                    нуждается в постоянном развитии и адаптации к новым условиям. 
                                    Немаловажную роль в этом процессе играет формирование эффективной 
                                    команды, способной быстро реагировать на изменения и предлагать 
                                    инновационные решения. Компания «Электрорешения», официальный 
                                    представитель бренда EKF в России, активно внедряет современные 
                                    тренды в HR, доказывая готовность к вызовам будущего.
                                </p>
                                <p class="st-main--p__DESCR2 __C-SCRL DOWN"> 
                                    В рамках панельной дискуссии «Стратегии и планы на 2025 год. 
                                    Как меняются стратегии управления талантами?» зимней сессии 
                                    Talent Management Forum директор по персоналу ООО «Электрорешения» 
                                    Марина Петухова поделилась опытом привлечения и удержания лучших 
                                    специалистов отрасли. Она акцентировала внимание на необходимости 
                                    пересмотра традиционных стратегий управления талантами. Ключевыми 
                                    вызовами 2025 года становятся цифровизация, повышение операционной 
                                    эффективности и непрерывное развитие сотрудников. Важно не просто 
                                    привлекать новых специалистов, но и удерживать текущих, создавая 
                                    им условия для профессионального и личного роста.
                                </p>
                            </div>

                            <div class="hr-polt--div__IMAGES_MAIN">
                                <div class="hr-polt--div__IMAGES __C-SCRL DOWN">
                                    <div class="hr-polt--div__IMAGE_CONT">
                                        <img class="hr-polt--img__IMAGE" src="images/home/hm-des_3.png" alt="" loading="lazy">
                                    </div>
                                    <div class="hr-polt--div__IMAGE_ADD1"></div>
                                    <div class="hr-polt--div__IMAGE_ADD2"></div>
                                </div>
            
                                <div class="hr-polt--div__IMAGES_TEXT __C-SCRL LEFT">
                                    <p class="st-main--p__DESCR1 __C-SCRL DOWN">
                                        Мы стараемся обеспечить инженерно-технический, 
                                        производственный и административный персонал всем 
                                        необходимым оборудованием для выполнения задач и 
                                        создать комфортные условия для продуктивной работы.
                                    </p>
                
                                    <p class="st-main--p__DESCR2 _THIRD __C-SCRL DOWN"> 
                                        При выходе на работу в «АТБ Электроника» сотрудники 
                                        включаются в индивидуальную программу адаптации и обучения.
                                        Формулируются задачи и ожидаемые результаты. В процессе 
                                        обеспечивается конструктивная обратная связь.
                                    </p>
                
                                    <a class="hr-polt--a__DETAIL __C-SCRL DOWN" href="#">
                                        <span class="hr-polt--span__DETAIL">
                                            Подробнее о процессе адаптации
                                        </span>
                                        <svg class="hr-polt--svg__DETAIL" width="28" height="22" viewBox="0 0 28 22" fill="none" xmlns="http://www.w3.org/2000/svg">
                                            <path d="M0 10.6953H27.5M27.5 10.6953L17 0.195312M27.5 10.6953L17 21.1953" stroke="#59CD90" stroke-width="0.55"/>
                                        </svg>
                                    </a>
                                </div>
                            </div>

                            <div class="hr-polt--div__IMAGES_MAIN _SECOND">
                                <div class="hr-polt--div__IMAGES _SECOND __C-SCRL DOWN">
                                    <div class="hr-polt--div__IMAGE_CONT">
                                        <img class="hr-polt--img__IMAGE" src="images/home/hm-des_1.png" alt="" loading="lazy">
                                    </div>
                                    <div class="hr-polt--div__IMAGE_ADD1 _SECOND"></div>
                                    <div class="hr-polt--div__IMAGE_ADD2 _SECOND"></div>
                                </div>
        
                                <div class="hr-polt--div__IMAGES_TEXT _SECOND __C-SCRL RIGHT">
                                    <p class="st-main--p__DESCR1 _SECOND __C-SCRL DOWN">
                                        Каждый сотрудник нашей команды является не только специалистом 
                                        и профессионалом, но также личностью с индивидуальными желаниями, 
                                        потребностями и мотивацией. Мы понимаем, что приоритетом является 
                                        баланс между профессиональным развитием и ростом, материальным 
                                        благополучием и возможностью вести интересную, здоровую и 
                                        насыщенную личную жизнь, заботиться о семье и близких.
                                    </p>
                
                                    <p class="st-main--p__DESCR2 _SECOND __C-SCRL DOWN"> 
                                        Для этого мы обеспечиваем комфортные условия работы, 
                                        развиваем корпоративные программы медицинского страхования, 
                                        оплаты фитнеса, проводим тренинги, корпоративные мероприятия 
                                        и тимбилдинги.
                                    </p>
                
                                    <p class="st-main--p__DESCR2 __C-SCRL DOWN"> 
                                        Ежедневное время работы в компании сокращено на 30 минут за счёт 
                                        уменьшения времени обеденного перерыва. В пятницу рабочий день 
                                        сокращён на час для сохранения баланса работа/жизнь.
                                    </p>
                
                                    <a class="hr-polt--a__DETAIL _SECOND __C-SCRL DOWN" href="#">
                                        <span class="hr-polt--span__DETAIL">
                                            Подробная информация о преимуществах 
                                            работы в «АТБ Электроника» 
                                        </span>
                                        <svg class="hr-polt--svg__DETAIL" width="28" height="22" viewBox="0 0 28 22" fill="none" xmlns="http://www.w3.org/2000/svg">
                                            <path d="M0 10.6953H27.5M27.5 10.6953L17 0.195312M27.5 10.6953L17 21.1953" stroke="#59CD90" stroke-width="0.55"/>
                                        </svg>
                                    </a>
                                </div>
                            </div>

                            <div class="hr-blog--div__POPUP_TEXT2">
                                <p class="st-main--p__DESCR2 __C-SCRL DOWN"> 
                                    Руководитель центра развития персонала и корпоративной культуры 
                                    «Электрорешения» Александра Наумова представила основные тезисы 
                                    развития корпоративной культуры и обучения внутри компании на 
                                    конференции Университета РАЭК.
                                </p>
                                <p class="st-main--p__DESCR2 __C-SCRL DOWN"> 
                                    Первый аспект — это непрерывное обучение и развитие. В компании 
                                    создается атмосфера, где с первого дня сотрудники погружаются 
                                    в процесс освоения новых знаний. Непрерывное обучение и развитие 
                                    становятся фундаментом для профессионального успеха каждого члена 
                                    команды.Второй ключевой момент — сильная школа внутренних экспертов. 
                                    Корпоративный университет компании предлагает различные форматы 
                                    обучения, как очные, так и онлайн, что дает возможность каждому 
                                    сотруднику развиваться под руководством опытных специалистов.
                                </p>
                                <p class="st-main--p__DESCR2 __C-SCRL DOWN"> 
                                    Не менее важна качественная поддержка на этапе адаптации. Новый 
                                    сотрудник получает всестороннюю помощь, позволяющую ему быстро 
                                    освоиться и интегрироваться в команду. Эти меры способствуют 
                                    комфортному вхождению в должность.
                                </p>
                                <p class="st-main--p__DESCR2 __C-SCRL DOWN"> 
                                    По завершении испытательного срока сотрудники не остаются без 
                                    внимания. Развитие ключевых навыков и компетенций продолжается 
                                    через практики регулярного менеджмента, что стимулирует 
                                    движение вперед и открытие новых горизонтов.
                                </p>
                                <p class="st-main--p__DESCR2 __C-SCRL DOWN"> 
                                    Культура постоянного совершенствования в ООО «Электрорешения» - это 
                                    не просто слова, а реальная стратегия, благодаря которой сотрудники 
                                    чувствуют себя частью большой команды, объединенной общей целью.
                                </p>
                                <p class="st-main--p__DESCR2 __C-SCRL DOWN"> 
                                    Комплексный подход к обучению и адаптации позволяет компании сохранять 
                                    один из самых низких показателей текучести на испытательном сроке — всего 3%. 
                                    Постоянная забота о сотрудниках и активная поддержка на всех этапах карьеры 
                                    укрепляют команду и готовят ее к вызовам будущего.
                                </p>
                            </div>

